create table if not exists public.timeline_daw_arrangement_items (id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,kind text not null check(kind in('marker','section')),name text not null check(char_length(name) between 1 and 120),color text not null,start_tick bigint not null check(start_tick>=0),end_tick bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((kind='marker' and end_tick is null) or(kind='section' and end_tick>start_tick)));
create index if not exists timeline_daw_arrangement_items_order on public.timeline_daw_arrangement_items(owner_id,session_id,start_tick);
alter table public.timeline_daw_arrangement_items enable row level security;
create policy timeline_daw_arrangement_items_owner_all on public.timeline_daw_arrangement_items for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create table if not exists public.timeline_daw_arrangement_item_edits(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,item_id text not null,before_state jsonb,after_state jsonb,state text not null default 'applied' check(state in('applied','undone')),created_at timestamptz not null default now(),changed_at timestamptz not null default now());
alter table public.timeline_daw_arrangement_item_edits enable row level security;
create policy timeline_daw_arrangement_item_edits_owner_all on public.timeline_daw_arrangement_item_edits for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
